update matter_codex_agent_sessions set
	codex_session_id = case when $2 <> '' then $2 else codex_session_id end,
	session_archive_gzip_base64 = case when $3 <> '' then $3 else session_archive_gzip_base64 end,
	status = case when $4 <> '' then $4 else status end,
	active_turn_id = null,
	active_run_id = '',
	last_activity_at = now(),
	expires_at = case when $5 > 0 then now() + make_interval(secs => $5::int) else expires_at end,
	updated_at = now()
where session_key = $1
returning
	id,
	session_key,
	project_id,
	chat_id,
	role_id,
	session_scope,
	mattermost_channel_id,
	mattermost_root_post_id,
	codex_session_id,
	status,
	coalesce(active_turn_id, 0),
	active_run_id,
	kubernetes_namespace,
	pod_name,
	pvc_name,
	token_secret_ref,
	capabilities::text,
	session_archive_gzip_base64,
	ttl_seconds,
	last_activity_at,
	expires_at,
	created_at,
	updated_at,
	openai_account_name;
